class FixedClock(datetime):
    @classmethod
    def now(cls, tz: object = None) -> datetime:
        current = datetime(2026, 10, 3, 10, 5, tzinfo=UTC)
        return current if tz is not None else current.replace(tzinfo=None)


@dataclass
